/**
 * 埋め込みフォント（欧文2書体）。
 *
 * 配布先の端末にフォントが無いと文字パーツが崩れるため、SVG-as-image でも
 * 確実に読める形（base64 の woff2 を data: URI で埋め込み）で持つ。
 * 外部ファイル参照は一切しない（README の Phase 0 検証ルール4）。
 *
 * 日本語は同梱しない方針（1書体で数MBになり、40KB上限に収まらないため）。
 * 日本語入力は端末の標準フォントに委ねる。ここに置くのは欧文の latin サブセットのみ。
 *
 * --- Dancing Script (Bold, latin subset) ---
 *   デザイナー: Pablo Impallari, Igino Marini (Impallari Type)
 *   ライセンス: SIL Open Font License 1.1
 *   入手元: Google Fonts (https://fonts.google.com/specimen/Dancing+Script)
 *           CSS: https://fonts.googleapis.com/css2?family=Dancing+Script:wght@700
 *           woff2: https://fonts.gstatic.com/s/dancingscript/v29/If2cXTr6YS-zF4S-kcSWSVi_sxjsohD9F50Ruu7B1i03Sup8.woff2
 *   バージョン: v29 (latin サブセット, unicode-range U+0000-00FF 他)
 *   OFLの全文は https://openfontlicense.org/ を参照。改変・再配布は同ライセンス継承で可。
 *
 * --- Quicksand (Bold, latin subset) ---
 *   デザイナー: Andrew Paglinawan (Kimberly Geswein 版に基づく)
 *   ライセンス: SIL Open Font License 1.1
 *   入手元: Google Fonts (https://fonts.google.com/specimen/Quicksand)
 *           CSS: https://fonts.googleapis.com/css2?family=Quicksand:wght@700
 *           woff2: https://fonts.gstatic.com/s/quicksand/v37/6xK-dSZaM9iE8KbpRA_LJ3z8mH9BOJvgkBgv58a-wg.woff2
 *   バージョン: v37 (latin サブセット, unicode-range U+0000-00FF 他)
 *   OFLの全文は https://openfontlicense.org/ を参照。改変・再配布は同ライセンス継承で可。
 *
 * advance（1文字あたりの平均送り幅 ÷ font-size）の実測方法:
 *   Chromeのcanvas 2D contextで各書体を200pxで読み込み、
 *   'AaBbCcDdEeFfGgHhIiJj'（大小混在の英字20文字）と
 *   'MikaYukiHanaSora2026'（英数字混在の名前風文字列）の2種類を
 *   measureText() で計測し、width / (fontSize * 文字数) を平均した。
 *   script: (0.4634 + 0.4974) / 2 = 0.4804 -> 0.48
 *   sans:   (0.5599 + 0.5655) / 2 = 0.5627 -> 0.56
 *   （スペースを含む文長い文はスペース幅で平均が下がるため、初期字・短い単語という
 *     実際の用途に近い、スペース無しの2サンプルの平均を採用した）
 */

export const FONTS = [
  {
    id: 'script',
    name: '筆記体',
    family: 'NdScript',
    advance: 0.48,
    dataUri: 'data:font/woff2;base64,',
  },
  {
    id: 'sans',
    name: '丸ゴシック',
    family: 'NdSans',
    advance: 0.56,
    dataUri: 'data:font/woff2;base64,',
  },
];

/** id で探す。見つからなければ FONTS[0]（筆記体）を返す */
export function getFont(id) {
  return FONTS.find(f => f.id === id) || FONTS[0];
}

/**
 * 指定した id ぶんだけの @font-face 定義を連結して返す。
 * 使っていない書体まで埋め込むと SVG が数MBになる（欧文2書体で計60KB弱ある）ため、
 * 実際にそのデザインで使われている書体だけを渡すこと。
 */
export function fontFaceCss(ids) {
  const list = Array.isArray(ids) ? ids : [ids];
  return list
    .map(id => getFont(id))
    .filter(Boolean)
    .map(f => `@font-face { font-family: '${f.family}'; font-weight: 400 700; src: url(${f.dataUri}) format('woff2'); }`)
    .join('');
}
